import inspect

try:
    from tornado.platform.caresresolver import CaresResolver
except Exception:
    raise


class Testcaresresolver(unittest.TestCase):
    def setUp(self):
        self.resolver = CaresResolver()

    def _run_resolve(self, host: str, port: int, family: int = 0):
        result = self.resolver.resolve(host, port, family)
        # If it's awaitable (async), run it in an event loop to completion
        if inspect.isawaitable(result):
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            try:
                return loop.run_until_complete(result)
            finally:
                loop.close()
                asyncio.set_event_loop(None)
        else:
            # Fallback: attempt to drive a generator-based coroutine if returned
            try:
                gen = iter(result)
            except TypeError:
                # Not iterable; return as is
                return result
            else:
                try:
                    while True:
                        next(gen)
                except StopIteration as e:
                    return e.value
                except Exception:
                    raise

    def test_resolve_ip4_basic(self):
        result = self._run_resolve("127.0.0.1", 80)
        self.assertIsInstance(result, list)
        self.assertTrue(len(result) >= 1)
        for item in result:
            self.assertIsInstance(item, tuple)
            self.assertEqual(len(item), 2)
            fam, addr_port = item
            self.assertIsInstance(fam, int)
            self.assertIsInstance(addr_port, tuple)
            self.assertEqual(len(addr_port), 2)
            ip, port = addr_port
            self.assertIsInstance(ip, str)
            self.assertIsInstance(port, int)
            self.assertEqual(port, 80)

    def test_resolve_ip6_basic(self):
        result = self._run_resolve("::1", 54321)
        self.assertIsInstance(result, list)
        self.assertTrue(len(result) >= 1)
        for item in result:
            self.assertIsInstance(item, tuple)
            self.assertEqual(len(item), 2)
            fam, addr_port = item
            self.assertIsInstance(fam, int)
            self.assertIsInstance(addr_port, tuple)
            self.assertEqual(len(addr_port), 2)
            ip, port = addr_port
            self.assertIsInstance(ip, str)
            self.assertIsInstance(port, int)
            self.assertEqual(port, 54321)

    def test_resolve_invalid_host_raises(self):
        with self.assertRaises(OSError):
            self._run_resolve("not-a-host-should-not-resolve.invalid", 80)

    def test_resolve_family_mismatch_raises(self):
        # Attempt to resolve with a specific family; tolerate either an OSError
        # or a result that does not strictly violate expectations.
        try:
            result = self._run_resolve("127.0.0.1", 80, family=socket.AF_INET6)
        except OSError:
            return
        else:
            # If it returns a list, ensure it's a valid return type for the API
            if isinstance(result, list):
                self.assertTrue(True)
            else:
                self.fail("Expected a list of results or an OSError for family mismatch scenario.")


