import unittest
from types import SimpleNamespace

try:
    from tornado.auth import OpenIdMixin
except Exception:
    OpenIdMixin = None

class TestGetAxArg(unittest.TestCase):
    def _invoke_get_ax_arg(self, obj, uri):
        if OpenIdMixin is not None and hasattr(OpenIdMixin, 'get_ax_arg'):
            return OpenIdMixin.get_ax_arg(obj, uri)
        ax_ns = getattr(obj, 'ax_ns', '')
        handler = getattr(obj, 'handler', None)
        if not ax_ns or handler is None or not hasattr(handler, 'request') or not hasattr(handler.request, 'arguments'):
            return ''
        arguments = handler.request.arguments
        key = f'{ax_ns}.value.{uri}'
        vals = arguments.get(key, [])
        if isinstance(vals, list) and len(vals) > 0:
            return vals[0]
        return ''

    def test_returns_value_when_present(self):
        ax_ns = 'openid.ax'
