        obj = SimpleNamespace(ax_ns=ax_ns, handler=SimpleNamespace(request=SimpleNamespace(arguments=arguments)))
        result = self._invoke_get_ax_arg(obj, uri)
        self.assertEqual(value, result)

    def test_returns_empty_when_missing(self):
        ax_ns = 'openid.ax'
